def dlogpdf_dlink_dtheta(self, f, y, Y_metadata=None):
    dlogpdf_dlink_dvar = self.dlogpdf_dlink_dvar(f, y, Y_metadata=Y_metadata)
    dlogpdf_dlink_dv = np.zeros_like(dlogpdf_dlink_dvar)
    # Calculate the derivative with respect to variance
    dlogpdf_dlink_dv = (self.v * (self.v + 1) * (-y + f)) / ((self.sigma2 * self.v + (y - f)**2)**2)
    return np.array((dlogpdf_dlink_dvar, dlogpdf_dlink_dv))
